let rawCode = $input.first().json.output; 
rawCode = rawCode.replace(/```python/g, '').replace(/```/g, '');
rawCode = rawCode.replace(/\\n/g, '\n');
rawCode = rawCode.trim();
const exportLine = `\n\nbpy.ops.export_scene.gltf(filepath="/tmp/student_workspace.glb", export_format='GLB')`;
const finalizedPythonCode = rawCode + exportLine;
return [{ json: { clean_python_code: finalizedPythonCode } }];

const raw = $('Message a model').first().json.output[0].content[0].text;

return [
  {
    json: {
      assessment_plan: JSON.parse(raw)
    }
  }
];

//code to calculate the mission score out of 100
const knowledgeScore = $input.first().json.knowledge_score || 0;
const curiosityScore = $input.first().json.curiosity_score || 0;

const missionScore =
  Number(knowledgeScore) + 10 + (curiosityScore * 40) / 100;

return [
  {
    json: {
      mission_score: Math.round(missionScore)
    }
  }
];

parameters.query:
-- A query to update responce score in assesment responses table
UPDATE public.assessment_responses

SET response_score = {{ $json.response_score }}

WHERE id = (

    SELECT id
    FROM public.assessment_responses
    WHERE objective_id = {{ $('objective_id').item.json.id }}
    ORDER BY id DESC
    LIMIT 1

)

RETURNING response_score;

UPDATE public.assessment_objectives

SET topic_analysis = LEAST(
    COALESCE(topic_analysis, 0)
    + {{ JSON.parse($('AI Agent5').item.json.output).topic_analysis_score }},
    100
)

WHERE id = {{ $('objective_id').item.json.id }}

RETURNING
    id,
    topic_analysis;

SELECT *
FROM assessment_objectives
WHERE assessment_session_id = {{ $('create a session').item.json.id }}
AND status = 'ACTIVE'
LIMIT 1;

SELECT EXISTS (
    SELECT 1
    FROM assessment_sessions
    WHERE user_id = '{{ $('Webhook1').item.json.body.id }}'
    AND status = 'ACTIVE'
) AS assessment_session_exists;

